// ============================================================================
// SPRITE CONFIG — tweak how characters look and behave, no art files needed.
// ============================================================================
//
// Right now every character is drawn as a simple colored shape (a "block
// person") generated by the game itself — that's what BootScene.js does.
// This keeps the prototype playable with zero image files, and it's a great
// first place for a kid to experiment: change a color, change a number,
// reload the page, see what happens.
//
// LATER, when you're ready to draw real sprites (in Piskel, Aseprite, or
// even just squared-off pixel art in any drawing program), you can replace
// the generateCharacterTexture() calls in BootScene.js with this.load.image()
// / this.load.spritesheet() calls instead. Everything else (movement, sword,
// AI) will keep working the same way because it only cares about the
// texture *key* (like "player" or "slime"), not how that texture was made.
// ============================================================================

export const PLAYER_CONFIG = {
  key: "player",
  size: 24,              // width/height in pixels
  bodyColor: 0x3fa7d6,   // tunic color (classic Zelda green is 0x2e8b57 — try it!)
  outlineColor: 0x1c2833,
  speed: 140,            // pixels per second
  maxHealth: 6,          // number of heart pieces (each heart = 2 health)
  invulnerableMs: 900,   // how long you flash/can't be hurt after taking damage
};

export const SWORD_CONFIG = {
  color: 0xe0e0e0,
  length: 22,
  thickness: 6,
  activeMs: 160,   // how long the sword hitbox stays out per swing
  cooldownMs: 250, // time before you can swing again
  damage: 1,
};

